DROP TABLE IF EXISTS `logs_auditoria`;
CREATE TABLE `logs_auditoria` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `utilizador_id` int(10) unsigned DEFAULT NULL,
