DROP TABLE IF EXISTS `servicos`;
CREATE TABLE `servicos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(25) NOT NULL,
  `cliente_id` int(10) unsigned NOT NULL,
